from flask import Blueprint, request, jsonify
from app.models.user import User
from app.database import db

user_controller = Blueprint('user', __name__)
    user_bp = Blueprint('user', __name__)

    @user_bp.route('/users', methods=['GET'])
        try:
            users = User.query.all()
            user_list = [{'id': user.id, 'username': user.username, 'email': user.email} for user in users]
            return jsonify({'users': user_list}), 200
        except Exception as e:
            return jsonify({'error': 'Failed to fetch users', 'details': str(e)}), 500

    @user_bp.route('/users/<int:user_id>', methods=['GET'])
        try:
            user = User.query.get(user_id)
            if not user:
                return jsonify({'error': 'User not found'}), 404
            user_data = {'id': user.id, 'username': user.username, 'email': user.email}
            return jsonify({'user': user_data}), 200
        except Exception as e:
            return jsonify({'error': 'Failed to fetch user', 'details': str(e)}), 500

    @user_bp.route('/users', methods=['POST'])
        try:
            data = request.get_json()
            username = data.get('username')
            email = data.get('email')

            if not username or not email:
                return jsonify({'error': 'Missing required fields: username and email'}), 400

            new_user = User(username=username, email=email)
            db.session.add(new_user)
            db.session.commit()

            return jsonify({'message': 'User created successfully', 'user': {'id': new_user.id, 'username': new_user.username, 'email': new_user.email}}), 201
        except Exception as e:
            return jsonify({'error': 'Failed to create user', 'details': str(e)}), 500

    @user_bp.route('/users/<int:user_id>', methods=['PUT'])
        try:
            user = User.query.get(user_id)
            if not user:
                return jsonify({'error': 'User not found'}), 404

            data = request.get_json()
            username = data.get('username')
            email = data.get('email')

            if username:
                user.username = username
            if email:
                user.email = email

            db.session.commit()

            return jsonify({'message': 'User updated successfully', 'user': {'id': user.id, 'username': user.username, 'email': user.email}}), 200
        except Exception as e:
            return jsonify({'error': 'Failed to update user', 'details': str(e)}), 500

    @user_bp.route('/users/<int:user_id>', methods=['DELETE'])
        try:
            user = User.query.get(user_id)
            if not user:
                return jsonify({'error': 'User not found'}), 404

            db.session.delete(user)
            db.session.commit()

            return jsonify({'message': 'User deleted successfully'}), 200
        except Exception as e:
            return jsonify({'error': 'Failed to delete user', 'details': str(e)}), 500

    return user_bp

